/* Shared code following partupd; generated by tools/overlay_src.py, stubs replaced by C as functions are matched.
   Starts at 0x002803B8 (was partupd_002803B8.c). */
#include "common.h"
#include "structs/particle.h"
#include "include_asm.h"
#include "asm_functions/executable.h"
#include "game/moby/mobyutil.h"

typedef int u128 __attribute__((mode(TI)));

extern int truncate_float_to_s32(float);
extern unsigned char *batalia_part_type49_textures;

// Spawns a particle of the given kind at pos with velocity vel.
void create_type_49_particle(void *pos, int kind, void *vel, float f) {
    float v[4];
    unsigned char *p;
    float *vp = v;
    *(u128 *)v = *(u128 *)vel;
    p = create_part(0x49);
    if (p != 0) {
        float s = 0.0f;
        int c = 0;
        switch (kind) {
            case 0:
                c = 0x20;
                s = 0.12f;
                random_float_between(0.25f, 0.25f);
                break;
            case 1:
                c = 0xD;
                s = 0.5f;
                random_float_between(1.0f, 1.0f);
                break;
        }
        ((struct PartBase *)p)->timer = scale_ticks(0x37);
        ((struct PartBase *)p)->color = (c << 24) | 0xFFFFFF;
        ((struct PartBase *)p)->unk_09 = truncate_float_to_s32(4.0f) + 0x20;
        ((struct PartBase *)p)->blend = 0x48;
        ((struct PartBase *)p)->unk_01 = 0;
        ((struct PartBase *)p)->texture = batalia_part_type49_textures[kind];
        ((struct PartBase *)p)->size = s * 210000.0f;
        ((struct PartBase *)p)->spin = (int)random_float_between(0.0f, 360.0f);
        *(u128 *)&((struct PartBase *)p)->pos = *(u128 *)pos;
        *(u128 *)(p + 0x20) = *(u128 *)vp;
        *(float *)(p + 0x2C) = f;
    }
}
